import (
	&quot;container/list&quot;
	&quot;fmt&quot;
)

type Entry struct {
	key, val string
}

type LRUCache struct {
	capacity int
	items    map[string]*list.Element
	evictList *list.List
}

func NewLRUCache(cap int) *LRUCache {
	return &amp;LRUCache{
		capacity:  cap,
		items:     make(map[string]*list.Element),
		evictList: list.New(),
	}
}

func (c *LRUCache) Get(key string) (string, bool) {
	if elem, ok := c.items[key]; ok {
		c.evictList.MoveToFront(elem)
		return elem.Value.(*Entry).val, true
	}
	return &quot;&quot;, false
}

func (c *LRUCache) Put(key, val string) {
	if elem, ok := c.items[key]; ok {
		c.evictList.MoveToFront(elem)
		elem.Value.(*Entry).val = val
		return
	}
	if c.evictList.Len() &gt;= c.capacity {
		oldest := c.evictList.Back()
		if oldest != nil {
			c.evictList.Remove(oldest)
			delete(c.items, oldest.Value.(*Entry).key)
		}
	}
	elem := c.evictList.PushFront(&amp;Entry{key: key, val: val})
	c.items[key] = elem
}

func main() {
	lru := NewLRUCache(2)
	lru.Put(&quot;k1&quot;, &quot;v1&quot;)
	lru.Put(&quot;k2&quot;, &quot;v2&quot;)
	fmt.Println(lru.Get(&quot;k1&quot;)) // v1, true
	lru.Put(&quot;k3&quot;, &quot;v3&quot;)         // вытесняет k2
	fmt.Println(lru.Get(&quot;k2&quot;)) // &quot;&quot;, false
	fmt.Println(lru.Get(&quot;k3&quot;)) // v3, true
