import (
    &quot;fmt&quot;
    &quot;io&quot;
    &quot;net/http&quot;
    &quot;sync&quot;
    &quot;time&quot;
)

type Result struct { URL string; Status int; Err error }

func download(urls []string, workers int) []Result {
    if workers &lt; 1 { workers = 1 }
    client := &amp;http.Client{Timeout: 5 * time.Second}
    jobs := make(chan string)
    results := make(chan Result, len(urls))
    var wg sync.WaitGroup
    for i := 0; i &lt; workers; i++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            for url := range jobs {
                resp, err := client.Get(url)
                if err != nil { results &lt;- Result{URL: url, Err: err}; continue }
                _, readErr := io.Copy(io.Discard, resp.Body)
                closeErr := resp.Body.Close()
                if readErr != nil { err = readErr } else if closeErr != nil { err = closeErr }
                results &lt;- Result{URL: url, Status: resp.StatusCode, Err: err}
            }
        }()
    }
    go func() {
        for _, url := range urls { jobs &lt;- url }
        close(jobs)
        wg.Wait()
        close(results)
    }()
    out := make([]Result, 0, len(urls))
    for result := range results { out = append(out, result) }
    return out
}

func main() {
    for _, result := range download([]string{&quot;https://example.com&quot;}, 3) {
        fmt.Println(result.URL, result.Status, result.Err)
    }
}

