var alphabet = []rune{&#x27;a&#x27;, &#x27;b&#x27;, &#x27;c&#x27;, &#x27;d&#x27;, &#x27;1&#x27;, &#x27;2&#x27;, &#x27;3&#x27;}

func hashPassword(pass string) []byte {
	h := md5.Sum([]byte(pass))
	return h[:]
}

func RecoverPassword(targetHash []byte, maxLen int) string {
	var generate func(prefix string, length int) string
	generate = func(prefix string, length int) string {
		if length == 0 {
			if bytes.Equal(hashPassword(prefix), targetHash) {
				return prefix
			}
			return &quot;&quot;
		}
		for _, ch := range alphabet {
			if res := generate(prefix+string(ch), length-1); res != &quot;&quot; {
				return res
			}
		}
		return &quot;&quot;
	}

	for l := 1; l &lt;= maxLen; l++ {
		if res := generate(&quot;&quot;, l); res != &quot;&quot; {
			return res
		}
	}
	return &quot;&quot;
}

func main() {
	testPassword := &quot;c1&quot;
	targetHash := hashPassword(testPassword)
    fmt.Printf(&quot;Ищем исходный пароль для хэша: %x\n&quot;, targetHash)
    recovered := RecoverPassword(targetHash, 3)
    fmt.Printf(&quot;Успешно восстановлен пароль: %s\n&quot;, recovered)
}

