func merge(cs ...&lt;-chan int) &lt;-chan int {
	out := make(chan int)
	var wg sync.WaitGroup

	for _, c := range cs {
		wg.Add(1)
		go func(ch &lt;-chan int) {
			defer wg.Done()
			for val := range ch {
				out &lt;- val
			}
		}(c)
	}

	go func() {
		wg.Wait()
		close(out)
	}()

	return out
}

func gen(nums ...int) &lt;-chan int {
	out := make(chan int)
	go func() {
		for _, n := range nums {
			out &lt;- n
		}
		close(out)
	}()
	return out
}

func main() {
	c1 := gen(1, 2, 3)
	c2 := gen(10, 20, 30)
	c3 := gen(100, 200)

	for val := range merge(c1, c2, c3) {
