func isMonotonic(arr []int) bool {
	if len(arr) &lt;= 2 {
		return true
	}
	inc, dec := true, true
	for i := 1; i &lt; len(arr); i++ {
		if arr[i] &gt; arr[i-1] {
			dec = false
		}
		if arr[i] &lt; arr[i-1] {
			inc = false
		}
	}
	return inc || dec
}

