func zip(s1 []int, s2 []int) [][]int {
	minLen := len(s1)
	if len(s2) &lt; minLen {
		minLen = len(s2)
	}
	res := make([][]int, minLen)
	for i := 0; i &lt; minLen; i++ {
		res[i] = []int{s1[i], s2[i]}
	}
	return res
}

