func uniqRandn(n int) []int {
	r := rand.New(rand.NewSource(time.Now().UnixNano()))
	seen := make(map[int]bool, n)
	res := make([]int, 0, n)

	for len(res) &lt; n {
		val := r.Intn(n * 10)
		if !seen[val] {
			seen[val] = true
			res = append(res, val)
		}
	}
	return res
}

