// Детект через pprof:
import _ "net/http/pprof"
// Смотреть: http://localhost:6060/debug/pprof/goroutine?debug=1

type slice struct {
    array unsafe.Pointer // указатель на массив
    len   int            // текущая длина
    cap   int            // емкость
}

func worker(id int, jobs <-chan int, results chan<- int, wg *sync.WaitGroup) {
    defer wg.Done()
    for j := range jobs {
        results <- j * 2
    }
}

func main() {
    jobs := make(chan int, 100)
    results := make(chan int, 100)
    var wg sync.WaitGroup

    for w := 1; w <= 3; w++ { // 3 воркера
        wg.Add(1)
        go worker(w, jobs, results, &wg)
    }
    for j := 1; j <= 5; j++ { jobs <- j }
    close(jobs)
    wg.Wait()
    close(results)
}

type K8sClient interface {
    GetPod(ctx context.Context, name string) (*Pod, error)
}

// В тестах передаем мок:
type MockK8sClient struct {
    mock.Mock
}
func (m *MockK8sClient) GetPod(ctx context.Context, name string) (*Pod, error) {
    args := m.Called(ctx, name)
    return args.Get(0).(*Pod), args.Error(1)
}
